from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            # Ignore the connected background, which often has a full-grid bounding box.
            if r0 == 0 and c0 == 0 and r1 == h-1 and c1 == w-1:
                continue
            if all(grid[y][x] == color for y in range(r0,r1+1) for x in range(c0,c1+1)
                   if y in (r0,r1) or x in (c0,c1)):
                frames.append((r0,r1,c0,c1,color))
    for r0,r1,c0,c1,color in frames:
        inner = [grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
        # Solid objects are not hollow frames; only recolor a distinct interior.
        if not inner or all(value == color for value in inner):
            continue
        ih, iw = r1-r0-1, c1-c0-1
        fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                out[r][c] = fill
    return out
